"""v55: F6 TEST -> TD Usage. The red-zone usage layer (build_redzone.py, J.rz) as player cards — expected vs actual TDs, red-zone
rushes, goal-line rushes (inside the 10), red-zone targets, end-zone targets, snap share, his team inside the 20 (PROE,
pass / run), the opponent's defense inside the 20 (PROE allowed, TD rate per trip) — scored 0-100, with the same data as a
sortable table. Window: the team's last five games or the season. Rerunnable (guarded)."""
import os, sys
P = os.path.join(os.path.dirname(os.path.abspath(__file__)), 'dashboard_template.html')
s = open(P, encoding='utf-8').read()
if 'function tdUsage()' in s:
    print('already applied'); sys.exit()
def rep(old, new, n=1):
    global s
    c = s.count(old); assert c == n, ('match count %d != %d for: %s' % (c, n, old[:100])); s = s.replace(old, new)

rep("{id:'numtake',nfl:true,label:'Numerology Takeaways',", "{id:'tdusage',nfl:true,label:'TD Usage',desc:'red-zone usage cards: expected vs actual touchdowns, red-zone and goal-line rushes, red-zone and end-zone targets, snap share, his team inside the 20 and the opponent\\'s defense inside the 20 \\u2014 scored 0-100, last five games or the season',c:'test',sub:'tdusage'},{id:'numtake',nfl:true,label:'Numerology Takeaways',")
rep('<div id="test" hidden><div id="numtake" hidden></div>', '<div id="test" hidden><div id="tdusage" hidden></div><div id="numtake" hidden></div>')
rep("if(it.c==='test'){['numtake','numer',", "if(it.c==='test'){['tdusage','numtake','numer',")
rep("['test',numerology],['test',numTake],", "['test',numerology],['test',numTake],['test',tdUsage],")
rep(" numtake:{what:'What the numbers actually say", " tdusage:{what:'Who is getting the touchdown work. Every rush and target a player had, weighted by the league TD rate at that yard line, is his expected touchdowns; beside it his actual, his red-zone and goal-line rushes, red-zone and end-zone targets and snap share, how his offense behaves inside the 20 and how the defense he faces this week behaves there.',how:['TD usage score = percentile blend: expected TDs per game .35 \\u00b7 red-zone opportunity share .20 \\u00b7 goal-line rushes + end-zone targets per game .20 \\u00b7 the opponent\\'s red-zone TD rate allowed .15 \\u00b7 his team\\'s red-zone trips per game .10','GL = rushes from the 10 in \\u00b7 EZ = targets thrown into the end zone \\u00b7 RZ share = his red-zone rushes + targets over his team\\'s red-zone plays \\u00b7 PROE = pass rate over expected inside the 20 (nflverse)','green = above expectation / soft defense, red = below / stingy \\u00b7 window = his team\\'s last five games or the season']},\n numtake:{what:'What the numbers actually say")
rep("/* v51 */#numer .nmgrid", r"""/* v55 */.tdug{display:grid;grid-template-columns:repeat(auto-fill,minmax(330px,1fr));gap:12px}.tuc{background:var(--s2);border:1px solid var(--edge);border-radius:12px;padding:12px 14px;min-width:0}.tuc .tu-hd{display:grid;grid-template-columns:40px 1fr 56px;gap:10px;align-items:center}.tuc .tu-hd .tu-nm{font-size:15px;font-weight:700;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.tuc .tu-hd .tu-sub{font-size:11px;color:var(--dim);font-family:var(--mono)}.tu-ring{position:relative;width:56px;height:56px;border-radius:50%;display:grid;place-items:center;font:700 16px var(--mono)}.tu-ring::after{content:'';position:absolute;inset:5px;border-radius:50%;background:var(--s2)}.tu-ring span{position:relative;z-index:1}.tu-ring.sm{width:44px;height:44px;font-size:12px}.tu-ring.sm::after{inset:4px}.tuc .tu-box{background:var(--s3);border-radius:9px;padding:8px 10px;margin:10px 0;display:grid;grid-template-columns:1fr 1.3fr 1fr;gap:8px;align-items:center}.tuc .tu-box .tu-k{font-size:10px;color:var(--dim)}.tuc .tu-box .tu-v{font:700 16px var(--mono)}.tuc .tu-pill{display:inline-block;padding:2px 8px;border-radius:6px;font:700 13px var(--mono)}.tuc .tu-pill.y{background:#3a3010;color:#e8b100}.tuc .tu-pill.g{background:#15351f;color:var(--green)}.tuc .tu-pill.r{background:#3a1512;color:var(--red)}.tuc .tu-dots i{display:inline-block;width:7px;height:7px;border-radius:50%;background:#b08a1a;margin-right:3px}.tuc .tu-u5{display:grid;grid-template-columns:repeat(4,1fr) 52px;gap:6px;align-items:end;text-align:center}.tuc .tu-u5 .tu-cell b{display:block;padding:4px 0;border-radius:6px;font:700 14px var(--mono)}.tuc .tu-u5 .tu-cell small{display:block;font-size:10px;color:var(--dim);margin-top:2px}.tuc .tu-u5 .tu-cell b.g{background:#15351f;color:var(--green)}.tuc .tu-u5 .tu-cell b.r{background:#3a1512;color:var(--red)}.tuc .tu-u5 .tu-cell b.n{background:var(--s3);color:var(--dim)}.tuc .tu-ln{display:flex;justify-content:space-between;align-items:center;font-size:12px;padding:5px 0;border-top:1px solid var(--edge)}.tuc .tu-ln:first-of-type{border-top:0}.tuc .tu-ln .tu-dim{color:var(--dim)}.tuc .tu-ln .tu-chip{font:700 12px var(--mono);border:1px solid;border-radius:6px;padding:1px 7px}.tuc .tu-ln .tu-chip.g{color:var(--green);border-color:var(--green)}.tuc .tu-ln .tu-chip.y{color:#e8b100;border-color:#e8b100}.tuc .tu-ln .tu-chip.r{color:var(--red);border-color:var(--red)}.tuc .tu-bar{display:inline-block;width:90px;height:5px;background:var(--s3);border-radius:3px;position:relative;vertical-align:middle;margin:0 6px}.tuc .tu-bar i{position:absolute;top:0;height:100%;border-radius:3px}.tuc .tu-bar b{position:absolute;top:-2px;width:1px;height:9px;background:var(--dim);left:50%}.tdt td{white-space:nowrap;vertical-align:middle}.tdt .tu-cellv{display:inline-block;min-width:36px;text-align:center;padding:2px 8px;border-radius:6px;font:700 12px var(--mono)}.tdt .tu-cellv.g{background:#15351f;color:var(--green)}.tdt .tu-cellv.r{background:#3a1512;color:var(--red)}.tdt .tu-cellv.n{background:var(--s3);color:var(--dim)}
/* v51 */#numer .nmgrid""")

rep("/* ---------------- v53: NUMEROLOGY TAKEAWAYS ---------------- */", r"""/* ---------------- v55: TD USAGE — the red-zone layer as cards ---------------- */
const RZ=J.rz||null;const RZC=RZ?Object.fromEntries(RZ.pcols.map((c,i)=>[c,i])):{};const RZT=RZ?Object.fromEntries(RZ.tcols.map((c,i)=>[c,i])):{};
const rzTeam=(side,scope,team)=>{if(!RZ)return null;const r=RZ.teams.find(x=>x[RZT.side]===side&&x[RZT.scope]===scope&&x[RZT.team]===team);return r?Object.fromEntries(RZ.tcols.map((c,i)=>[c,r[i]])):null};
const pctRank=(arr,v)=>{if(v==null||!arr.length)return null;const n=arr.filter(x=>x<v).length,e=arr.filter(x=>x===v).length;return (n+e/2)/arr.length};
function tdUsage(){const el=$('#tdusage');if(!el)return;if(!RZ){el.innerHTML='<div class="panel"><p class="note">no red-zone layer on file — run scripts/build_redzone.py (needs the nflverse pbp cache)</p></div>';return}
  const st=G.tdu||(G.tdu={scope:'l5',view:'cards',pos:'',min:1});const wk=G.week;
  const oppOf=t=>{const m=(J.matchups||[]).find(x=>x.team===t);return m?m.opponent:''};
  const PL=RZ.players.filter(r=>r[RZC.scope]===st.scope).map(r=>Object.fromEntries(RZ.pcols.map((c,i)=>[c,r[i]]))).filter(p=>/^(RB|WR|TE|QB|FB)$/.test(p.pos||'')&&(p.rush+p.tgt)>=5&&p.games>=st.min);
  PL.forEach(p=>{const o=oppOf(p.team);p.oppRaw=o;p.opp=o.replace('@','');p.off=rzTeam('off',st.scope,p.team);p.def=p.opp?rzTeam('def','season',p.opp):null;p.g=Math.max(1,p.games);p.xtdg=p.xtd/p.g;p.glez=(p.gl_rush+p.ez_tgt)/p.g;p.tripsg=p.off&&p.off.games?p.off.trips/p.off.games:null;p.oppTd=p.def?p.def.td_rate:null});
  const A={x:PL.map(p=>p.xtdg),s:PL.map(p=>p.rz_opp_share).filter(v=>v!=null),g:PL.map(p=>p.glez),d:PL.map(p=>p.oppTd).filter(v=>v!=null),t:PL.map(p=>p.tripsg).filter(v=>v!=null)};
  PL.forEach(p=>{const parts=[[pctRank(A.x,p.xtdg),.35],[pctRank(A.s,p.rz_opp_share),.20],[pctRank(A.g,p.glez),.20],[pctRank(A.d,p.oppTd),.15],[pctRank(A.t,p.tripsg),.10]].filter(x=>x[0]!=null);const w=parts.reduce((a,x)=>a+x[1],0);p.score=w?Math.round(100*parts.reduce((a,x)=>a+x[0]*x[1],0)/w):null});
  let R=PL.filter(p=>inF(p.team)&&(typeof inP!=='function'||inP(p.pos))&&(!st.pos||p.pos===st.pos)).sort((a,b)=>((b.opp?1:0)-(a.opp?1:0))||(b.score??-1)-(a.score??-1));R.forEach((p,i)=>p.rank=i+1);   /* bye weeks sink to the bottom */
  const ringC=v=>v==null?'var(--dim)':v>=85?'var(--green)':v>=65?'#8fc63f':v>=45?'#e8b100':'var(--red)';const ring=(v,cls='')=>`<div class="tu-ring ${cls}" style="background:conic-gradient(${ringC(v)} ${(v||0)*3.6}deg,var(--s3) 0)"><span style="color:${ringC(v)}">${v??'—'}</span></div>`;
  const snap=p=>p.snap_pct==null?null:Math.round(100*p.snap_pct);const cl=v=>v>0?'g':v===0?'r':'n';const sgn=v=>v==null?'—':(v>0?'+':'')+v.toFixed(1)+'%';const tdc=v=>v==null?'':v>=.6?'g':v>=.45?'y':'r';
  const bar=(v,max,neg)=>v==null?'':`<span class="tu-bar"><b></b><i style="${v>=0?`left:50%;width:${Math.min(50,50*v/max)}%`:`right:50%;width:${Math.min(50,50*-v/max)}%`};background:${v>=0?'var(--green)':'var(--red)'}"></i></span>`;
  const card=p=>{const d=p.td-p.xtd;const off=p.off,def=p.def;return `<div class="tuc"><div class="tu-hd">${tcell(p.team).replace('class="tc"','class="tc" style="font-size:12px"')}<div><div class="tu-nm plink" data-p="${esc(p.player)}">${esc(p.player)}</div><div class="tu-sub">#${p.rank} · ${p.pos} · ${p.oppRaw?(p.oppRaw[0]==='@'?'@ ':'vs ')+p.opp:'bye'} · ${p.games} game${p.games===1?'':'s'}</div></div>${ring(p.score)}</div>
    <div class="tu-box"><div><div class="tu-k">Expected TDs</div><span class="tu-pill y">${p.xtd.toFixed(2)}</span></div><div><div class="tu-k">Actual TDs</div><div class="tu-v">${p.td} <span class="tu-dots">${'<i></i>'.repeat(Math.min(p.td,12))}</span></div></div><div style="text-align:right"><div class="tu-k">TDs vs Exp.</div><span class="tu-pill ${d>0.25?'g':d<-0.25?'r':'y'}">${d>0?'+':''}${d.toFixed(2)}</span></div></div>
    <div class="tu-u5"><div class="tu-cell"><b class="${cl(p.rz_rush)}">${p.rz_rush}</b><small>RZ Rush</small></div><div class="tu-cell"><b class="${cl(p.gl_rush)}">${p.gl_rush}</b><small>GL Rush</small></div><div class="tu-cell"><b class="${cl(p.rz_tgt)}">${p.rz_tgt}</b><small>RZ Tgt</small></div><div class="tu-cell"><b class="${cl(p.ez_tgt)}">${p.ez_tgt}</b><small>EZ Tgt</small></div><div class="tu-cell">${ring(snap(p),'sm')}<small>Snaps</small></div></div>
    <div style="margin-top:10px"><div class="tu-ln"><span class="tu-dim">${p.team} inside the 20</span><span style="color:${off&&off.proe>0?'var(--green)':'var(--red)'}">${off?sgn(off.proe):'—'} PROE</span></div><div class="tu-ln" style="border-top:0;padding-top:0"><span><b style="color:#b08a1a">${off&&off.pass_pct!=null?Math.round(100*off.pass_pct)+'% pass':'—'}</b></span><span class="tu-dim">${off&&off.run_pct!=null?Math.round(100*off.run_pct)+'% run':''}</span></div>
    <div class="tu-ln"><span class="tu-dim">${p.opp||'—'} defense</span><span>${def?`<span style="color:${def.proe>0?'var(--green)':'var(--red)'}">${sgn(def.proe)} PROE</span> <span class="tu-chip ${tdc(def.td_rate)}">${Math.round(100*def.td_rate)}% TD</span>`:'<span class="tu-dim">—</span>'}</span></div>
    <div class="tu-ln" style="border-top:0;padding-top:0"><span class="tu-dim mini">RZ share ${p.rz_opp_share!=null?Math.round(100*p.rz_opp_share)+'%':'—'} · RZ TDs ${p.rz_td}</span><span class="tu-dim mini">${def?`${def.td_trips} of ${def.trips} trips`:''}</span></div></div></div>`};
  const table=`<div class="panel wrap-x"><table class="tdt"><thead><tr><th>#</th><th>player</th><th>RZ rush</th><th>GL rush</th><th>RZ tgt</th><th>EZ tgt</th><th>snaps</th><th>RZ share</th><th>PROE</th><th>pass %</th><th>run %</th><th>opp RZ PROE</th><th>opp RZ TD</th><th>xTD</th><th>TD</th><th>±</th><th>score</th></tr></thead><tbody>${R.map(p=>{const off=p.off,def=p.def,d=p.td-p.xtd;return `<tr><td class="mini">${p.rank}</td><td>${tcell(p.team)} <span class="plink" data-p="${esc(p.player)}"><b>${esc(p.player)}</b></span> <span class="mini dim">${p.pos} · ${p.oppRaw||'bye'} · ${p.games}g</span></td><td><span class="cellv ${cl(p.rz_rush)}">${p.rz_rush}</span></td><td><span class="cellv ${cl(p.gl_rush)}">${p.gl_rush}</span></td><td><span class="cellv ${cl(p.rz_tgt)}">${p.rz_tgt}</span></td><td><span class="cellv ${cl(p.ez_tgt)}">${p.ez_tgt}</span></td><td class="num" data-v="${snap(p)??-1}">${snap(p)!=null?snap(p)+'%':'—'}</td><td class="num" data-v="${p.rz_opp_share??-1}">${p.rz_opp_share!=null?Math.round(100*p.rz_opp_share)+'%':'—'}</td><td data-v="${off?off.proe:-99}"><span style="color:${off&&off.proe>0?'var(--green)':'var(--red)'}">${off?sgn(off.proe):'—'}</span>${off?bar(off.proe,25):''}</td><td class="num">${off&&off.pass_pct!=null?Math.round(100*off.pass_pct)+'%':''}</td><td class="num dim">${off&&off.run_pct!=null?Math.round(100*off.run_pct)+'%':''}</td><td data-v="${def?def.proe:-99}"><span style="color:${def&&def.proe>0?'var(--green)':'var(--red)'}">${def?sgn(def.proe):'—'}</span>${def?bar(def.proe,25):''}</td><td data-v="${def?def.td_rate:-1}">${def?`<span class="chip ${tdc(def.td_rate)}" style="font:700 12px var(--mono);border:1px solid;border-radius:6px;padding:1px 7px;color:${def.td_rate>=.6?'var(--green)':def.td_rate>=.45?'#e8b100':'var(--red)'}">${Math.round(100*def.td_rate)}%</span> <span class="mini dim">${def.td_trips} of ${def.trips}</span>`:'—'}</td><td class="num"><span class="tu-pill y" style="padding:1px 7px;border-radius:5px;font:700 12px var(--mono);background:#3a3010;color:#e8b100">${p.xtd.toFixed(2)}</span></td><td class="num"><b>${p.td}</b></td><td class="num" style="color:${d>0.25?'var(--green)':d<-0.25?'var(--red)':'var(--dim)'}">${d>0?'+':''}${d.toFixed(2)}</td><td data-v="${p.score??-1}">${ring(p.score,'sm')}</td></tr>`}).join('')}</tbody></table></div>`;
  const wkTxt=st.scope==='l5'?`his team's last ${RZ.window} games`:`the ${RZ.season} season`;
  el.innerHTML=`<div class="controls"><span class="chips" id="tduScope"><button data-s="l5" class="${st.scope==='l5'?'on':''}">last ${RZ.window} games</button><button data-s="season" class="${st.scope==='season'?'on':''}">season</button></span><span class="chips" id="tduView"><button data-v="cards" class="${st.view==='cards'?'on':''}">cards</button><button data-v="table" class="${st.view==='table'?'on':''}">table</button></span><span class="chips" id="tduPos"><button data-p="" class="${st.pos?'':'on'}">all</button>${['RB','WR','TE','QB'].map(x=>`<button data-p="${x}" class="${st.pos===x?'on':''}">${x}</button>`).join('')}</span><span class="note">${R.length} players with 5+ rushes or targets over ${wkTxt} · week ${wk} opponents · expected TDs = every rush and target weighted by the league TD rate at that yard line (rates fit on ${RZ.season-2}–${RZ.season}) · GL = rushes from the 10 in · EZ = targets thrown into the end zone · snaps = offensive snap share over the window · RZ share = his red-zone rushes + targets over his team's red-zone plays · PROE = pass rate over expected inside the 20 · opponent TD rate = TD drives per red-zone trip allowed this season · score = percentile blend (xTD/g .35 · RZ share .20 · GL + EZ per game .20 · opponent RZ TD rate .15 · team RZ trips/g .10) · pbp through week ${Math.max(...PL.map(p=>p.team_games))<wk?wk-1:wk}</span></div>
    ${st.view==='cards'?`<div class="tdug">${R.slice(0,120).map(card).join('')||'<p class="note">no one in view</p>'}</div>`:table}`;
  el.querySelectorAll('#tduScope button').forEach(b=>b.onclick=()=>{st.scope=b.dataset.s;tdUsage()});el.querySelectorAll('#tduView button').forEach(b=>b.onclick=()=>{st.view=b.dataset.v;tdUsage()});el.querySelectorAll('#tduPos button').forEach(b=>b.onclick=()=>{st.pos=b.dataset.p;tdUsage()});sortableAll(el)}
RR.push(()=>{if(CUR_ITEM==='tdusage')tdUsage()});
/* ---------------- v53: NUMEROLOGY TAKEAWAYS ---------------- */""")
s = s.replace("Object.assign(NOTES,{v54:", "Object.assign(NOTES,{v55:['v55','F6 TEST \\u2192 TD Usage: the red-zone layer (nflverse pbp) as player cards \\u2014 expected vs actual TDs, RZ / GL rushes, RZ / EZ targets, snap share, his team inside the 20, the opponent\\'s defense inside the 20 \\u2014 scored 0-100, last five games or the season, cards or table'],v54:", 1)
open(P, 'w', encoding='utf-8').write(s)
